252	     * the first eight upper-case hex characters of the SHA-256 of the owner's normalized telephone
253	     * concatenated with its last name (e.g. {@code NSW-3F5A9C2E}). The identity carries no sequence
254	     * number, so it depends only on the owner's own postcode, telephone and last name.
255	     *
256	     * <p>If the computed code collides with an existing owner's {@code customerCode}, {@code -<n>}
257	     * is appended with the smallest {@code n} of 2 or more that makes it unique, and the
258	     * de-duplicated code is returned.
259	     */
260	    private String generateCustomerCode(Owner owner) {
261	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
262	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
263	        String base = Regions.forPostcode(owner.getPostcode()) + "-" + hash8(telephone + lastName);
264	        return deduplicateCustomerCode(base, owner);
265	    }
