267	    /**
268	     * Return {@code base} if no other owner already uses it as a {@code customerCode}; otherwise
269	     * append {@code -<n>} with the smallest {@code n >= 2} that is not already taken, so distinct
270	     * owners always receive distinct customer codes.
271	     */
272	    private String deduplicateCustomerCode(String base, Owner owner) {
273	        Set<String> existing = ownerRepository.findAll().stream()
274	            .filter(other -> other != owner)
275	            .map(Owner::getCustomerCode)
276	            .filter(Objects::nonNull)
277	            .collect(Collectors.toSet());
278	        if (!existing.contains(base)) {
279	            return base;
280	        }
281	        int n = 2;
282	        while (existing.contains(base + "-" + n)) {
283	            n++;
284	        }
285	        return base + "-" + n;
286	    }
