291	     */
292	    private static String hash8(String value) {
293	        try {
294	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
295	            StringBuilder sb = new StringBuilder(8);
296	            for (int i = 0; i < 4; i++) {
297	                sb.append(String.format("%02X", digest[i]));
298	            }
