324	    /**
325	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
326	     * whitespace to a single space and lower-case the result, so values that differ only in
327	     * letter case or incidental whitespace are treated as equal. Shared by the household
328	     * (last name) and per-city matching rules.
329	     */
330	    private String normalizeForComparison(String value) {
331	        if (value == null) {
332	            return null;
333	        }
334	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
335	    }
