345	    @Override
346	    @Transactional(readOnly = true)
347	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
348	        String normalizedLastName = normalizeForComparison(owner.getLastName());
349	        String postcode = owner.getPostcode();
350	        if (normalizedLastName == null || postcode == null) {
351	            return null;
352	        }
353	        String telephone = owner.getTelephone();
354	        return ownerRepository.findAll().stream()
355	            .filter(existing -> existing.getId() != null)
356	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName())))
357	            .filter(existing -> postcode.equals(existing.getPostcode()))
358	            .filter(existing -> telephone == null
359	                ? existing.getTelephone() != null
360	                : !telephone.equals(existing.getTelephone()))
361	            .map(Owner::getId)
362	            .min(Integer::compareTo)
363	            .orElse(null);
364	    }
